import OpenAI from 'openai';
import type { StructuredLogger } from '../logging/structured-logger';
import type { UnifiedAgentResponseService } from './unified-agent-response.service';
import type { UnifiedAgentActionsService } from './unified-agent-actions.service';
import type { AgentRuntimeContextService } from './agent-runtime/agent-runtime.context';
import type { UnifiedAgentContextService } from './unified-agent-context.service';
import type { ActionEntry, PredecidedAction, ToolArgs } from './unified-agent.types';
import {
  buildPredecidedActionDraft,
  executePredecidedAgentActions,
  type PredecidedToolExecutor,
} from './unified-agent-predecided-actions.part';
import { actionSucceeded } from './unified-agent-tool-router.helpers';
import { recordAgentRuntimeTurn } from './unified-agent-runtime.helpers';

type UnknownRecord = Record<string, unknown>;

export async function processUnifiedAgentPredecidedActions(params: {
  logger: StructuredLogger;
  actions: UnifiedAgentActionsService;
  response: UnifiedAgentResponseService;
  agentRuntime?: AgentRuntimeContextService;
  ctx: UnifiedAgentContextService;
  openai: OpenAI | null;
  writerModel: string;
  fallbackWriterModel: string;
  executeTool: PredecidedToolExecutor;
  workspaceId: string;
  contactId: string;
  phone: string;
  message: string;
  context?: UnknownRecord;
  allowedTools?: string[];
  predecidedActions: PredecidedAction[];
  conversationHistory: Array<unknown>;
}): Promise<{
  actions: ActionEntry[];
  response?: string;
  intent: string;
  confidence: number;
}> {
  const {
    logger,
    actions,
    response,
    agentRuntime,
    ctx,
    openai,
    writerModel,
    fallbackWriterModel,
    executeTool,
    workspaceId,
    contactId,
    phone,
    message,
    context,
    allowedTools,
    predecidedActions,
    conversationHistory,
  } = params;

  const actionsList = await executePredecidedAgentActions({
    ...(allowedTools !== undefined ? { allowedTools } : {}),
    contactId,
    ...(context !== undefined ? { context } : {}),
    executeTool,
    logAutopilotEvent: actions.logAutopilotEvent.bind(actions),
    phone,
    predecidedActions,
    workspaceId,
  });
  const intent = response.extractIntent(actionsList, message);
  const draftedReply = await response.composeWriterReply(
    openai,
    writerModel,
    fallbackWriterModel,
    {
      workspaceId,
      customerMessage: message,
      assistantDraft: buildPredecidedActionDraft(actionsList),
      actions: actionsList,
      historyTurns: conversationHistory.length,
    },
  );

  await recordAgentRuntimeTurn(agentRuntime, {
    workspaceId,
    channel: ctx.readText(context?.channel, 'whatsapp'),
    userMessage: message,
    ...(draftedReply !== undefined ? { assistantMessage: draftedReply } : {}),
    contactId,
    intent,
    confidence: actionsList.length > 0 ? 0.85 : 0.55,
    actions: actionsList.map((action) => ({
      toolName: action.tool,
      success: actionSucceeded(action.result),
      result: action.result,
    })),
  });

  return {
    actions: actionsList,
    ...(draftedReply !== undefined ? { response: draftedReply } : {}),
    intent,
    confidence: actionsList.length > 0 ? 0.85 : 0.55,
  };
}

import type OpenAI from 'openai';
import type { StructuredLogger } from '../logging/structured-logger';
import type { UnifiedAgentActionsService } from './unified-agent-actions.service';
import type { ActionEntry, ToolArgs } from './unified-agent.types';
import { forEachSequential } from '../common/async-sequence';
import { isAllowedTool, parseToolArgs } from './unified-agent-tool-parser.helpers';
import {
  executeToolAction,
  type ExecuteToolActionDeps,
} from './unified-agent-tool-router.helpers';
import type { PredecidedToolExecutor } from './unified-agent-predecided-actions.part';

type UnknownRecord = Record<string, unknown>;

export async function processUnifiedAgentToolCalls(params: {
  logger: StructuredLogger;
  actions: UnifiedAgentActionsService;
  workspaceId: string;
  contactId: string;
  phone: string;
  allowedTools?: string[];
  context?: UnknownRecord;
  executeTool: PredecidedToolExecutor;
  assistantMessage: {
    tool_calls?: Array<{
      id: string;
      type: string;
      function: { name: string; arguments: string };
    }>;
  };
}): Promise<ActionEntry[]> {
  const {
    logger,
    actions,
    workspaceId,
    contactId,
    phone,
    allowedTools,
    context,
    executeTool,
    assistantMessage,
  } = params;

  const actionsList: ActionEntry[] = [];
  const executeTools = context?.executeTools !== false;

  if (executeTools && assistantMessage.tool_calls && assistantMessage.tool_calls.length > 0) {
    await forEachSequential(assistantMessage.tool_calls, async (toolCall) => {
      if (toolCall.type !== 'function') {
        return;
      }
      const toolName = toolCall.function.name;
      if (!isAllowedTool(toolName, allowedTools)) {
        logger.warn(
          `Blocked disallowed agent tool call: workspaceId=${workspaceId} tool=${toolName}`,
        );
        const blockedResult = { blocked: true, reason: 'capability_not_allowed' };
        actionsList.push({ tool: toolName, args: {} as ToolArgs, result: blockedResult });
        await actions.logAutopilotEvent(workspaceId, contactId, toolName, {} as ToolArgs, blockedResult);
        return;
      }
      const toolArgs = parseToolArgs(toolCall.function.arguments) as ToolArgs;
      const result = await executeTool(
        workspaceId,
        contactId,
        phone,
        toolName,
        toolArgs,
        context,
      );
      actionsList.push({ tool: toolName, args: toolArgs, result });
      await actions.logAutopilotEvent(workspaceId, contactId, toolName, toolArgs, result);
    });
  }

  return actionsList;
}

import type OpenAI from 'openai';
import type { ChatCompletionMessageParam } from 'openai/resources/chat';
import type { StructuredLogger } from '../logging/structured-logger';
import type { PrismaService } from '../prisma/prisma.service';
import type { AuditService } from '../audit/audit.service';
import type { PlanLimitsService } from '../billing/plan-limits.service';
import type { UnifiedAgentContextService } from './unified-agent-context.service';
import type { UnifiedAgentResponseService } from './unified-agent-response.service';
import type { UnifiedAgentActionsService } from './unified-agent-actions.service';
import type { AgentRuntimeContextService } from './agent-runtime/agent-runtime.context';
import type { AbiBuilderService } from './abi/abi-builder.service';
import type { RiskGateService } from './risk-class/risk-gate.service';
import type { ActionEntry, PredecidedAction } from './unified-agent.types';
import { chatCompletionWithFallback } from './openai-wrapper';
import { buildAgentRuntimeContext, recordAgentRuntimeTurn } from './unified-agent-runtime.helpers';
import { formatPromptValue } from './unified-agent-tool-parser.helpers';
import { buildUnifiedAgentCognitiveState } from './unified-agent-cognitive-state.helpers';
import {
  executeToolAction,
  actionSucceeded,
  type ExecuteToolActionDeps,
} from './unified-agent-tool-router.helpers';
import { processUnifiedAgentPredecidedActions } from './unified-agent-predecided-processing.helpers';
import { processUnifiedAgentToolCalls } from './unified-agent-tool-call-processing.helpers';

type UnknownRecord = Record<string, unknown>;

const UNIFIED_AGENT_PROVIDER_CONFIG_REQUIRED =
  'Primary LLM configuration is required for unified agent generation';

export async function processIncomingUnifiedAgentMessage(params: {
  openai: OpenAI | null;
  primaryBrainModel: string;
  fallbackBrainModel: string;
  writerModel: string;
  fallbackWriterModel: string;
  prisma: PrismaService;
  planLimits: PlanLimitsService;
  ctx: UnifiedAgentContextService;
  response: UnifiedAgentResponseService;
  actions: UnifiedAgentActionsService;
  logger: StructuredLogger;
  auditService: AuditService;
  abiBuilder?: AbiBuilderService;
  agentRuntime?: AgentRuntimeContextService;
  riskGate?: RiskGateService;
  allowedTools?: string[];
  predecidedActions?: PredecidedAction[];
  workspaceId: string;
  contactId: string;
  phone: string;
  message: string;
  context?: UnknownRecord;
}): Promise<{
  actions: ActionEntry[];
  response?: string;
  intent: string;
  confidence: number;
}> {
  const {
    openai,
    primaryBrainModel,
    fallbackBrainModel,
    writerModel,
    fallbackWriterModel,
    prisma,
    planLimits,
    ctx,
    response,
    actions,
    logger,
    auditService,
    abiBuilder,
    agentRuntime,
    riskGate,
    allowedTools,
    predecidedActions: predecidedActionsRaw,
    workspaceId,
    contactId,
    phone,
    message,
    context,
  } = params;

  const predecidedActions = predecidedActionsRaw ?? [];

  if (!openai && predecidedActions.length === 0) {
    logger.warn('OpenAI not configured');
    return response.buildFallbackResult(message);
  }

  const [workspace, contact, conversationHistory, products] = await Promise.all([
    ctx.getWorkspaceContext(workspaceId),
    ctx.getContactContext(workspaceId, contactId, phone),
    ctx.getConversationHistory(workspaceId, contactId, 0, phone),
    ctx.getProducts(workspaceId),
  ]);

  const productIds = products
    .map((product: UnknownRecord) => {
      const productValue = ctx.readRecord(product.value);
      return ctx.readOptionalText(productValue.id) || ctx.readOptionalText(product.id);
    })
    .filter((productId): productId is string => Boolean(productId));
  let aiConfigs: UnknownRecord[] = [];
  if (productIds.length > 0) {
    try {
      aiConfigs = await prisma.productAIConfig.findMany({
        take: 50,
        where: { productId: { in: productIds } },
        select: {
          id: true,
          productId: true,
          tone: true,
          persistenceLevel: true,
          messageLimit: true,
          customerProfile: true,
          positioning: true,
          objections: true,
          salesArguments: true,
        },
      });
    } catch {
      /* ProductAIConfig may not exist yet */
    }
  }

  const compressedContext = await ctx.buildAndPersistCompressedContext(
    workspaceId,
    contactId,
    phone,
    contact,
  );
  const tacticalHint = ctx.buildLeadTacticalHint({
    leadName: ctx.isRecord(contact) ? ctx.readText(contact.name).trim() : '',
    currentMessage: message,
    conversationHistory,
  });

  const agentRuntimeContext = await buildAgentRuntimeContext(agentRuntime, {
    workspaceId,
    channel: ctx.readText(context?.channel, 'whatsapp'),
    message,
    contactId,
    ...(allowedTools !== undefined ? { allowedTools } : {}),
  });
  const systemPrompt = [
    ctx.buildSystemPrompt(workspace, products, aiConfigs),
    agentRuntimeContext.systemPromptBlock,
  ].join('\n\n');
  const stylePolicy = response.buildReplyStyleInstruction(
    message,
    conversationHistory.length,
  );
  const contactData: Record<string, unknown> = ctx.isRecord(contact) ? contact : {};
  const contactName = ctx.readText(contactData.name).trim() || phone;
  const contactSentiment = ctx.readText(contactData.sentiment).trim() || 'NEUTRAL';
  const leadScore = ctx.readText(contactData.leadScore, '0');
  const tagNames = ctx.readTagList(contactData.tags);

  const additionalContext = context ? formatPromptValue(context) : '';
  const currentInput = {
    raw: message,
    channel: ctx.readText(context?.channel, 'whatsapp'),
    arrivalTimestamp: new Date().toISOString(),
  };
  const cognitiveState = await buildUnifiedAgentCognitiveState({
    abiBuilder,
    logger,
    currentInput,
  });

  const messages: ChatCompletionMessageParam[] = [
    ...conversationHistory,
    {
      role: 'user',
      content: JSON.stringify({
        cognitiveState,
        runtimeContext: {
          workspaceProductContext: systemPrompt,
          compressedMemory: compressedContext || null,
          additionalContext,
          tacticalHint:
            tacticalHint || 'responder com clareza, valor concreto e próximo passo.',
          responsePolicy: stylePolicy,
        },
        contact: {
          name: contactName,
          sentiment: contactSentiment,
          leadScore,
          tags: tagNames,
        },
        currentInput,
      }),
    },
  ];

  const toolActionDeps: ExecuteToolActionDeps = {
    logger,
    actions,
    riskGate,
    prisma,
    auditService,
    agentRuntime,
    openai,
    primaryBrainModel,
    fallbackBrainModel,
  };

  const executeTool = (
    wsId: string,
    ctId: string,
    ph: string,
    t: string,
    a: Record<string, unknown>,
    ctxParam?: UnknownRecord,
  ) =>
    executeToolAction(toolActionDeps, wsId, ctId, ph, t, a, ctxParam);

  if (predecidedActions.length > 0) {
    return processUnifiedAgentPredecidedActions({
      logger,
      actions,
      response,
      agentRuntime,
      ctx,
      openai,
      writerModel,
      fallbackWriterModel,
      executeTool,
      workspaceId,
      contactId,
      phone,
      message,
      context,
      allowedTools,
      predecidedActions,
      conversationHistory,
    });
  }

  let llmResponse: OpenAI.Chat.ChatCompletion;
  try {
    await planLimits.ensureTokenBudget(workspaceId);
    if (!openai) {
      throw new Error(UNIFIED_AGENT_PROVIDER_CONFIG_REQUIRED);
    }
    llmResponse = await chatCompletionWithFallback(
      openai,
      {
        model: primaryBrainModel,
        messages,
        temperature: 0.82,
        top_p: 0.9,
      },
      fallbackBrainModel,
    );
  } catch (err: unknown) {
    const msg = err instanceof Error ? err.message : typeof err === 'string' ? err : 'unknown';
    logger.error(`OpenAI agent processing failed, using fallback: ${msg}`);
    return response.buildFallbackResult(message);
  }
  if (!llmResponse) {
    return response.buildFallbackResult(message);
  }
  const firstChoice = llmResponse.choices[0];
  if (!firstChoice) {
    return response.buildFallbackResult(message);
  }
  await planLimits
    .trackAiUsage(workspaceId, llmResponse.usage?.total_tokens ?? 500)
    .catch(() => {});

  const assistantMessage = firstChoice.message;

  const actionsList = await processUnifiedAgentToolCalls({
    logger,
    actions,
    workspaceId,
    contactId,
    phone,
    allowedTools,
    context,
    executeTool,
    assistantMessage,
  });

  const intent = response.extractIntent(actionsList, message);
  const confidence = response.calculateConfidence(actionsList, llmResponse);
  const draftedReply = await response.composeWriterReply(
    openai,
    writerModel,
    fallbackWriterModel,
    {
      workspaceId,
      customerMessage: message,
      assistantDraft: assistantMessage.content,
      actions: actionsList,
      historyTurns: conversationHistory.length,
    },
  );

  await recordAgentRuntimeTurn(agentRuntime, {
    workspaceId,
    channel: ctx.readText(context?.channel, 'whatsapp'),
    userMessage: message,
    ...(draftedReply !== undefined ? { assistantMessage: draftedReply } : {}),
    contactId,
    intent,
    confidence,
    actions: actionsList.map((action) => ({
      toolName: action.tool,
      success: actionSucceeded(action.result),
      result: action.result,
    })),
  });

  return {
    actions: actionsList,
    ...(draftedReply !== undefined ? { response: draftedReply } : {}),
    intent,
    confidence,
  };
}

import { Injectable, Optional } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { StructuredLogger } from '../logging/structured-logger';
import OpenAI from 'openai';
import { PlanLimitsService } from '../billing/plan-limits.service';
import { AuditService } from '../audit/audit.service';
import { createTextLlmClient } from '../lib/llm-provider';
import { resolveBackendOpenAIModel } from '../lib/openai-models';
import { PrismaService } from '../prisma/prisma.service';
import { UnifiedAgentContextService } from './unified-agent-context.service';
import { UnifiedAgentResponseService } from './unified-agent-response.service';
import { UnifiedAgentActionsService } from './unified-agent-actions.service';
import { AgentRuntimeContextService } from './agent-runtime';
import { AbiBuilderService } from './abi/abi-builder.service';
import { RiskGateService } from './risk-class/risk-gate.service';
export type { ToolArgs, ActionEntry } from './unified-agent.types';
import type { ToolArgs, ActionEntry, PredecidedAction } from './unified-agent.types';
import { processIncomingUnifiedAgentMessage } from './unified-agent-incoming-message.helpers';
import {
  executeToolAction,
  type ExecuteToolActionDeps,
} from './unified-agent-tool-router.helpers';

type UnknownRecord = Record<string, unknown>;

@Injectable()
export class UnifiedAgentService {
  private readonly logger = StructuredLogger.from(UnifiedAgentService.name);
  private readonly openai: OpenAI | null;
  private readonly primaryBrainModel: string;
  private readonly fallbackBrainModel: string;
  private readonly writerModel: string;
  private readonly fallbackWriterModel: string;

  constructor(
    private readonly prisma: PrismaService,
    private readonly config: ConfigService,
    private readonly planLimits: PlanLimitsService,
    private readonly auditService: AuditService,
    private readonly ctx: UnifiedAgentContextService,
    private readonly response: UnifiedAgentResponseService,
    private readonly actions: UnifiedAgentActionsService,
    @Optional() private readonly agentRuntime?: AgentRuntimeContextService,
    @Optional() private readonly abiBuilder?: AbiBuilderService,
    @Optional() private readonly riskGate?: RiskGateService,
  ) {
    this.openai = createTextLlmClient(this.config);
    this.primaryBrainModel = resolveBackendOpenAIModel('brain', this.config);
    this.fallbackBrainModel = resolveBackendOpenAIModel('brain_fallback', this.config);
    this.writerModel = resolveBackendOpenAIModel('writer', this.config);
    this.fallbackWriterModel = resolveBackendOpenAIModel('writer_fallback', this.config);
  }

  async processIncomingMessage(params: {
    workspaceId: string;
    phone: string;
    message: string;
    contactId?: string;
    channel?: string;
    context?: UnknownRecord;
    executeTools?: boolean;
  }): Promise<{
    reply?: string;
    response?: string;
    actions: ActionEntry[];
    intent: string;
    confidence: number;
  }> {
    const result = await this.processMessage({
      workspaceId: params.workspaceId,
      contactId: params.contactId || '',
      phone: params.phone,
      message: params.message,
      context: {
        channel: params.channel || 'whatsapp',
        executeTools: params.executeTools !== false,
        ...(params.context || {}),
      },
    });

    return {
      actions: result.actions,
      intent: result.intent,
      confidence: result.confidence,
      ...(result.response !== undefined
        ? { reply: result.response, response: result.response }
        : {}),
    };
  }

  async processMessage(params: {
    allowedTools?: string[];
    predecidedActions?: PredecidedAction[];
    workspaceId: string;
    contactId: string;
    phone: string;
    message: string;
    context?: UnknownRecord;
  }): Promise<{
    actions: ActionEntry[];
    response?: string;
    intent: string;
    confidence: number;
  }> {
    return processIncomingUnifiedAgentMessage({
      openai: this.openai,
      primaryBrainModel: this.primaryBrainModel,
      fallbackBrainModel: this.fallbackBrainModel,
      writerModel: this.writerModel,
      fallbackWriterModel: this.fallbackWriterModel,
      prisma: this.prisma,
      planLimits: this.planLimits,
      ctx: this.ctx,
      response: this.response,
      actions: this.actions,
      logger: this.logger,
      auditService: this.auditService,
      abiBuilder: this.abiBuilder,
      agentRuntime: this.agentRuntime,
      riskGate: this.riskGate,
      ...params,
    });
  }

  async executeTool(
    tool: string,
    args: ToolArgs,
    ctx: { workspaceId: string; contactId?: string; phone?: string },
  ): Promise<unknown> {
    return executeToolAction(
      this.toolActionDeps(),
      ctx.workspaceId,
      ctx.contactId || '',
      ctx.phone || '',
      tool,
      args,
    );
  }

  async buildQuotedReplyPlan(params: {
    workspaceId: string;
    contactId?: string;
    phone: string;
    draftReply: string;
    customerMessages: Array<{ content: string; quotedMessageId: string }>;
  }): Promise<Array<{ quotedMessageId: string; text: string }>> {
    return this.response.buildQuotedReplyPlan(
      this.openai,
      this.writerModel,
      this.fallbackWriterModel,
      this.planLimits,
      params,
    );
  }

  private toolActionDeps(): ExecuteToolActionDeps {
    return {
      logger: this.logger,
      actions: this.actions,
      riskGate: this.riskGate,
      prisma: this.prisma,
      auditService: this.auditService,
      agentRuntime: this.agentRuntime,
      openai: this.openai,
      primaryBrainModel: this.primaryBrainModel,
      fallbackBrainModel: this.fallbackBrainModel,
    };
  }
}

